        );
    }
    if !view.lanes.is_empty() {
        say!("lanes:");
    }
    for l in &view.lanes {
        let sha = |s: &Option<String>| s.as_deref().map_or("-".to_owned(), |s| short(s).to_owned());
        say!(
            "  {} {} {} base {} head {} pushed {}{}{}",
            l.name,
            l.branch,
            l.worktree.display(),
