            sha(&l.pushed_head),
            if l.removed { " (removed)" } else { "" },
            brought_up_clause(&view, l)
        );
    }
    if let Some(order) = merge_order_line(&view, pipeline.as_ref()) {
        say!("merge order: {order}");
    }
    for a in view.attempts.iter().filter(|a| a.ended_ms.is_none()) {
